+/**
+ * A text file based implementation of a {@link ViolationStore}.<br>
+ * This {@link ViolationStore} stores the violations of every single rule in a dedicated file and keeps an index
+ * named {@code stored.rules} in the configured folder.
+ *
+ * <p>The store can be configured through the following properties:</p>
+ * <pre><code>
+ * default.path=...               # string: the folder where violation files are stored
+ * default.allowStoreCreation=... # boolean: whether a new index may be created
+ * default.allowStoreUpdate=...   # boolean: whether store files may be updated
+ * default.fileNames=random|description|... # how new violation files are named
+ * default.integrity=ignore|repair|fail     # integrity policy for initialization
+ * </code></pre>
+ */
+@PublicAPI(usage = ACCESS)
+public final class TextFileBasedViolationStore implements ViolationStore {
+    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);
+
+    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
+    private static final Pattern ONLY_LINE_BREAKS_PATTERN = Pattern.compile("[\\r\\n]*");
+    private static final Pattern DESCRIPTION_WORD_PATTERN = Pattern.compile("[A-Za-z0-9]{4,120}");
+
+    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
+    private static final String STORE_PATH_DEFAULT = "archunit_store";
+    private static final String STORED_RULES_FILE_NAME = "stored.rules";
+    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
+    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
+    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
+    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
+    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
+    private static final String FILE_NAMES_RANDOM = "random";
+    private static final String FILE_NAMES_DESCRIPTION = "description";
+    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
+    private static final String INTEGRITY_IGNORE = "ignore";
+    private static final String INTEGRITY_REPAIR = "repair";
+    private static final String INTEGRITY_FAIL = "fail";
+
+    /* The lock is deliberately per canonical folder, not per store instance. */
+    private static final ConcurrentHashMap<String, Object> STORE_LOCKS = new ConcurrentHashMap<>();
+    private static final ConcurrentHashMap<String, FileSyncedProperties> STORED_RULES_BY_PATH = new ConcurrentHashMap<>();
+
+    private final RuleViolationFileNameStrategy constructorStrategy;
+
+    private boolean constructorStrategyConfigured;
+    private boolean storeCreationAllowed;
+    private boolean storeUpdateAllowed;
+    private File storeFolder;
+    private FileSyncedProperties storedRules;
+    private FileNameMode fileNameMode;
+    private RuleViolationFileNameStrategy activeStrategy;
+    private IntegrityMode integrityMode;
+
+    /**
+     * Creates a standard store. New files are named randomly unless {@code default.fileNames=description} is set.
+     *
+     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
+     */
+    public TextFileBasedViolationStore() {
+        constructorStrategy = null;
+    }
+
+    /**
+     * Creates a store with a custom strategy for rule violation file names.
+     *
+     * @param ruleViolationFileNameStrategy controls how new rule violation file names are derived
+     */
+    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
+        if (ruleViolationFileNameStrategy == null) {
+            throw new IllegalArgumentException("Rule violation file name strategy must not be null");
+        }
+        constructorStrategy = ruleViolationFileNameStrategy;
+        constructorStrategyConfigured = true;
+    }
+
+    @Override
+    public void initialize(Properties properties) {
+        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        configureFileNames(properties);
+        integrityMode = configureIntegrity(properties);
+
+        try {
+            storeFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT)).getCanonicalFile();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+
+        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Integrity repair requires %s.%s=true",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        String folderKey = storeFolder.getPath();
+        Object lock = STORE_LOCKS.computeIfAbsent(folderKey, ignored -> new Object());
+        synchronized (lock) {
+            initializeLocked(folderKey);
+        }
+    }
+
+    private void configureFileNames(Properties properties) {
+        if (constructorStrategyConfigured) {
+            if (properties.containsKey(FILE_NAMES_PROPERTY_NAME)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "%s cannot be configured for a store constructed with a RuleViolationFileNameStrategy",
+                        FILE_NAMES_PROPERTY_NAME));
+            }
+            fileNameMode = FileNameMode.CUSTOM;
+            activeStrategy = constructorStrategy;
+            return;
+        }
+
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_RANDOM);
+        if (FILE_NAMES_RANDOM.equals(configured)) {
+            fileNameMode = FileNameMode.RANDOM;
+            activeStrategy = description -> UUID.randomUUID().toString();
+        } else if (FILE_NAMES_DESCRIPTION.equals(configured)) {
+            fileNameMode = FileNameMode.DESCRIPTION;
+            activeStrategy = TextFileBasedViolationStore::descriptionFileName;
+        } else {
+            fileNameMode = FileNameMode.CUSTOM;
+            activeStrategy = instantiateStrategy(configured);
+        }
+    }
+
+    private IntegrityMode configureIntegrity(Properties properties) {
+        String configured = properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_IGNORE);
+        if (INTEGRITY_IGNORE.equals(configured)) {
+            return IntegrityMode.IGNORE;
+        }
+        if (INTEGRITY_REPAIR.equals(configured)) {
+            return IntegrityMode.REPAIR;
+        }
+        if (INTEGRITY_FAIL.equals(configured)) {
+            return IntegrityMode.FAIL;
+        }
+        throw new StoreInitializationFailedException(String.format(
+                "Invalid %s '%s' (accepted values: %s, %s, %s)",
+                INTEGRITY_PROPERTY_NAME, configured, INTEGRITY_REPAIR, INTEGRITY_FAIL, INTEGRITY_IGNORE));
+    }
+
+    private RuleViolationFileNameStrategy instantiateStrategy(String className) {
+        try {
+            Class<?> type = Class.forName(className);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(type)) {
+                throw new IllegalArgumentException("does not implement RuleViolationFileNameStrategy");
+            }
+            Constructor<?> constructor = type.getConstructor();
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException |
+                 InvocationTargetException | ClassCastException | IllegalArgumentException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate %s configured by %s=%s; it must be a public RuleViolationFileNameStrategy with a public no-argument constructor",
+                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, className), e);
+        }
+    }
+
+    private void initializeLocked(String folderKey) {
+        File storedRulesFile = new File(storeFolder, STORED_RULES_FILE_NAME);
+        log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesFile.getAbsolutePath());
+
+        boolean indexExists = Files.exists(storedRulesFile.toPath(), LinkOption.NOFOLLOW_LINKS);
+        if (!indexExists && !storeCreationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+        if (indexExists && !isRegularFileDirectlyInFolder(storedRulesFile)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Violation store index %s must be a regular file directly in the store folder",
+                    storedRulesFile.getAbsolutePath()));
+        }
+
+        Properties properties = indexExists ? loadProperties(storedRulesFile) : new Properties();
+        IntegrityReport report = null;
+        if (integrityMode != IntegrityMode.IGNORE) {
+            report = inspect(properties);
+            if (integrityMode == IntegrityMode.FAIL && report.hasProblems()) {
+                throw new StoreInitializationFailedException(report.message(storeFolder));
+            }
+            if (integrityMode == IntegrityMode.REPAIR) {
+                properties = repair(properties, report);
+            }
+        }
+
+        ensureFolderAndIndex(storedRulesFile, indexExists);
+        if (!indexExists || (integrityMode == IntegrityMode.REPAIR && report != null && report.entriesChanged)) {
+            writeProperties(storedRulesFile, properties);
+        }
+
+        FileSyncedProperties state = STORED_RULES_BY_PATH.computeIfAbsent(
+                storedRulesFile.getPath(), ignored -> new FileSyncedProperties(storedRulesFile));
+        state.replace(properties);
+        storedRules = state;
+    }
+
+    private void ensureFolderAndIndex(File storedRulesFile, boolean indexExists) {
+        if (Files.exists(storeFolder.toPath(), LinkOption.NOFOLLOW_LINKS) &&
+                !Files.isDirectory(storeFolder.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Violation store path %s is not a folder", storeFolder.getAbsolutePath()));
+        }
+        if (!Files.exists(storeFolder.toPath(), LinkOption.NOFOLLOW_LINKS) && !storeFolder.mkdirs() && !storeFolder.isDirectory()) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot create violation store folder %s", storeFolder.getAbsolutePath()));
+        }
+        if (!indexExists) {
+            try {
+                if (!storedRulesFile.createNewFile() && !isRegularFileDirectlyInFolder(storedRulesFile)) {
+                    throw new IOException("Could not create index");
+                }
+            } catch (IOException e) {
+                throw new StoreInitializationFailedException(e);
+            }
+        }
+    }
+
+    private Properties loadProperties(File file) {
+        Properties result = new Properties();
+        try (FileInputStream inputStream = new FileInputStream(file)) {
+            result.load(inputStream);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        return result;
+    }
+
+    private IntegrityReport inspect(Properties properties) {
+        IntegrityReport report = new IntegrityReport();
+        List<EntryInfo> entries = new ArrayList<>();
+        for (String description : properties.stringPropertyNames()) {
+            String recordedName = properties.getProperty(description);
+            entries.add(new EntryInfo(description, recordedName, deriveExistingName(description, recordedName)));
+        }
+        entries.sort(Comparator.comparing(entry -> entry.description));
+
+        Path folderPath = storeFolder.toPath();
+        Path folderRealPath = realPathIfPresent(folderPath);
+        Map<String, List<EntryInfo>> entriesByRecordedName = new HashMap<>();
+        for (EntryInfo entry : entries) {
+            entry.path = folderPath.resolve(entry.recordedName);
+            entry.resolvedPath = resolveRegularFileDirectlyInFolder(entry.path, folderRealPath);
+            entry.broken = entry.resolvedPath == null;
+            if (!entry.broken) {
+                try {
+                    entry.resolved = readLines(entry.resolvedPath).isEmpty();
+                } catch (RuntimeException e) {
+                    entry.broken = true;
+                }
+            }
+            entry.misplaced = !entry.recordedName.equals(entry.derivedName);
+            entriesByRecordedName.computeIfAbsent(entry.recordedName, ignored -> new ArrayList<>()).add(entry);
+        }
+
+        for (EntryInfo entry : entries) {
+            List<EntryInfo> sameRecordedName = entriesByRecordedName.get(entry.recordedName);
+            entry.shared = sameRecordedName.size() > 1 || sharesResolvedFile(entry, entries);
+            entry.destinationOccupied = entry.misplaced && destinationOccupied(entry, entries, folderRealPath);
+            report.add(entry);
+        }
+
+        if (Files.isDirectory(folderPath, LinkOption.NOFOLLOW_LINKS)) {
+            try (DirectoryStream<Path> files = Files.newDirectoryStream(folderPath)) {
+                Set<String> recordedNames = entriesByRecordedName.keySet();
+                for (Path file : files) {
+                    if (STORED_RULES_FILE_NAME.equals(file.getFileName().toString()) || recordedNames.contains(file.getFileName().toString())) {
+                        continue;
+                    }
+                    if (Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS)) {
+                        report.unownedFiles.add(file.getFileName().toString());
+                    }
+                }
+            } catch (IOException e) {
+                throw new StoreInitializationFailedException(e);
+            }
+        }
+        Collections.sort(report.unownedFiles);
+        return report;
+    }
+
+    private String deriveExistingName(String description, String recordedName) {
+        if (fileNameMode == FileNameMode.RANDOM) {
+            // Random names cannot be re-created. The name recorded by the index is their derived name.
+            return recordedName;
+        }
+        return createName(description, true);
+    }
+
+    private String createName(String description, boolean initializing) {
+        String name;
+        try {
+            name = activeStrategy.createRuleFileName(description);
+        } catch (RuntimeException e) {
+            throw nameCreationFailure(initializing, e);
+        }
+        if (name == null || name.isEmpty()) {
+            throw nameCreationFailure(initializing, new IllegalArgumentException("The strategy returned no name"));
+        }
+        return name;
+    }
+
+    private RuntimeException nameCreationFailure(boolean initializing, Throwable cause) {
+        String message = "Rule violation file name strategy returned no usable name";
+        return initializing ? new StoreInitializationFailedException(message, cause) : new StoreUpdateFailedException(message);
+    }
+
+    private static String descriptionFileName(String description) {
+        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description);
+        String word = "rule";
+        while (matcher.find()) {
+            word = matcher.group();
+        }
+        return word + "-" + sha256(description).substring(0, 40);
+    }
+
+    private static String sha256(String value) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder();
+            for (byte current : digest) {
+                result.append(String.format("%02x", current & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new AssertionError(e);
+        }
+    }
+
+    private boolean destinationOccupied(EntryInfo entry, List<EntryInfo> entries, Path folderRealPath) {
+        Path destination = storeFolder.toPath().resolve(entry.derivedName);
+        if (!isDirectPath(destination, folderRealPath)) {
+            return true;
+        }
+        for (EntryInfo other : entries) {
+            if (other != entry && entry.derivedName.equals(other.recordedName)) {
+                return true;
+            }
+        }
+        return Files.exists(destination, LinkOption.NOFOLLOW_LINKS);
+    }
+
+    private boolean sharesResolvedFile(EntryInfo entry, List<EntryInfo> entries) {
+        if (entry.resolvedPath == null) {
+            return false;
+        }
+        for (EntryInfo other : entries) {
+            if (other != entry && other.resolvedPath != null) {
+                try {
+                    if (Files.isSameFile(entry.resolvedPath, other.resolvedPath)) {
+                        return true;
+                    }
+                } catch (IOException ignored) {
+                    // The entry will still be dealt with as broken by its own resolution.
+                }
+            }
+        }
+        return false;
+    }
+
+    private Properties repair(Properties original, IntegrityReport report) {
+        Properties repaired = copyOf(original);
+        for (EntryInfo entry : report.entries) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                repaired.remove(entry.description);
+                report.entriesChanged = true;
+            } else if (entry.resolved) {
+                deleteEntryFile(entry);
+                repaired.remove(entry.description);
+                report.entriesChanged = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.destinationOccupied) {
+                moveEntryFile(entry);
+                repaired.setProperty(entry.description, entry.derivedName);
+                report.entriesChanged = true;
+            }
+        }
+        return repaired;
+    }
+
+    private void deleteEntryFile(EntryInfo entry) {
+        if (isIndexPath(entry.path)) {
+            return;
+        }
+        try {
+            if (entry.resolvedPath != null) {
+                Files.deleteIfExists(entry.resolvedPath);
+            }
+            if (Files.isSymbolicLink(entry.path)) {
+                Files.deleteIfExists(entry.path);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot remove resolved violation file '%s'", entry.recordedName), e);
+        }
+    }
+
+    private void moveEntryFile(EntryInfo entry) {
+        if (isIndexPath(entry.path) || isIndexName(entry.derivedName)) {
+            return;
+        }
+        Path destination = storeFolder.toPath().resolve(entry.derivedName);
+        try {
+            Files.move(entry.resolvedPath, destination);
+            if (Files.isSymbolicLink(entry.path)) {
+                Files.deleteIfExists(entry.path);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot move violation file for rule '%s' to '%s'", entry.description, entry.derivedName), e);
+        }
+    }
+
+    private IntegrityReport reportForSave(Properties properties) {
+        return inspect(properties);
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        return storedRules.containsKey(rule.getDescription());
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        Object lock = STORE_LOCKS.get(storeFolder.getPath());
+        synchronized (lock) {
+            Properties original = loadProperties(new File(storeFolder, STORED_RULES_FILE_NAME));
+            storedRules.replace(original);
+            String description = rule.getDescription();
+            String existingName = original.getProperty(description);
+
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                forgetUnderRepair(original, description);
+                return;
+            }
+
+            boolean newEntry = existingName == null;
+            String name = newEntry ? createName(description, false) : existingName;
+            validateSaveTarget(original, description, name, newEntry);
+
+            Path target = targetForSave(name, newEntry);
+            FileBackup backup = newEntry ? FileBackup.none() : backup(target);
+            try {
+                writeViolations(violations, target);
+                if (newEntry) {
+                    Properties updated = copyOf(original);
+                    updated.setProperty(description, name);
+                    writeProperties(new File(storeFolder, STORED_RULES_FILE_NAME), updated);
+                    storedRules.replace(updated);
+                }
+                backup.discard();
+            } catch (RuntimeException e) {
+                backup.restore();
+                throw e;
+            }
+        }
+    }
+
+    private void forgetUnderRepair(Properties original, String description) {
+        String recordedName = original.getProperty(description);
+        if (recordedName == null) {
+            return;
+        }
+        IntegrityReport report = reportForSave(original);
+        EntryInfo entry = report.entryFor(description);
+        if (entry == null) {
+            return;
+        }
+        Properties updated = copyOf(original);
+        updated.remove(description);
